def v(x:Any,f="Por verificar"):return f if x in(None,"",[],{}) else str(x)
def pd(x):
 try:return date.fromisoformat(str(x)[:10]) if x else None
 except:return None
def de(x):
 d=pd(x); m=("enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre")
 return f"{d.day} de {m[d.month-1]} de {d.year}" if d else v(x,"Fecha por verificar")
