def sig(a,l):return {"heading":"FIRMA","_type":"signature","heading_align":"center","parties":[{"label":l,"name":who(a),"id":v(a.get("requester_id") or a.get("owner_id"),"")}]}
def start(h,p):return {"heading":h,"paragraphs":p,"_suppress_default_control":True}
def addr(a):
 o=str(a.get("official_address") or "");u=str(a.get("used_address") or "")
 return ("Inconsistencia aparente de dirección",f"Dato oficial informado: «{o}». Dato usado: «{u}». Debe obtenerse certificación histórica RUNT de la fecha de consulta, trazabilidad de la fuente, guía postal y soporte de notificación subsidiaria; la diferencia no produce por sí sola nulidad.") if o and u and o.casefold()!=u.casefold() else ("Notificación por reconstruir","Envío, entrega, subsidiaria y conocimiento real deben probarse separadamente.")
def notif(a):
 l,d=addr(a);return ["Detección, validación y envío son hitos distintos: controlar validación frente a diez (10) días hábiles y envío frente a tres (3) días hábiles siguientes a la validación.","La comparecencia en fotodetección se prevé dentro de once (11) días hábiles siguientes al recibo; despacho o guía no equivalen a recibo.","Si no se surte la notificación en la última dirección registrada, debe acreditarse el mecanismo subsidiario realmente utilizado.","Conocimiento tardío por consulta o cobro no equivale automáticamente a notificación válida.","Si se prueba falta o indebida notificación, el art. 136 dispone que los términos de reducción corran desde la notificación válida; otros efectos exigen reconstruir el expediente y la afectación material de defensa.",f"Clasificación preliminar: {l}. {d}"]
def owner(a):return ["C-038/2020 eliminó la solidaridad automática propietario-conductor: la titularidad sola no traslada una conducta ajena.","C-321/2022 precisó que el art. 10 de Ley 2161 contiene deberes propios del propietario; para lugares/horarios no permitidos, velocidad y luz roja, sancionarlo exige prueba de incumplimiento culposo dentro del procedimiento, no responsabilidad objetiva.","La autoridad debe individualizar si imputa conducción o deber propio del propietario, norma, hechos, prueba y culpabilidad, con oportunidad real de contradicción."]
def terms(a):return [f"Caducidad: art. 161, un (1) año desde el hecho para decidir la imposición de sanción. Hecho: {de(a.get('detection_date'))}; decisión: {de(a.get('sanction_date'))}. Sin acto y fecha ciertos no se declara.",f"Prescripción: art. 159, tres (3) años desde el hecho; se interrumpe con la notificación del mandamiento de pago. Mandamiento: {de(a.get('payment_order_date'))}. Sin expediente coactivo no se concluye.","Caducidad, prescripción, ejecutoria y cobro son controles distintos."]
