def record(a,r):return [start("ASUNTO Y ALCANCE",[f"Petición del expediente del comparendo {v(a.get('citation_number'))}, placa {v(a.get('vehicle_plate'))}. No acepta infracción, conducción, ejecutoria ni deuda."]),{"heading":"I. DETECCIÓN Y VALIDACIÓN","numbered":["Original y metadatos de evidencia.","Registro de validación, fecha/hora y funcionario competente.","Identificación del SAST, punto y soportes del período."]},{"heading":"II. DATOS Y NOTIFICACIÓN","numbered":["Certificación histórica RUNT a la fecha consultada.",f"Explicar fuente del dato usado: oficial informado «{v(a.get('official_address'))}»; utilizado «{v(a.get('used_address'))}».","Guía, imposición, intentos, entrega/devolución y certificación postal.","Notificación electrónica, aviso o subsidiaria con contenido y fechas.","Precisar actuación que produjo vinculación e inicio de defensa."]},{"heading":"III. SANCIÓN Y COBRO","numbered":["Audiencias, actas, grabaciones y pruebas.","Resolución sancionatoria íntegra, notificación, recursos y ejecutoria.","Calidad de imputación y juicio de responsabilidad.","Si existe cobro: título, mandamiento, notificación, excepciones, acuerdos y cautelares.","Pagos y novedades SIMIT/RUNT."]},{"heading":"IV. TÉRMINOS Y RESERVA","numbered":["Información/documentos: diez (10) días; demás peticiones: en principio quince (15), salvo regla especial.","Incompetencia: traslado dentro de cinco (5) días.","Reserva: norma específica y versión pública cuando proceda.","Documento inexistente/no custodiado: declararlo expresamente."]},sig(a,"PERSONA PETICIONARIA")]
def claim(a,r):
 l,d=addr(a);return [start("REGLA DE ACTIVACIÓN",["Solo procede con evidencia que permita cuestionar la notificación; no convierte ‘no recibí’ en nulidad automática.",f"{l}. {d}"]),{"heading":"I. HECHOS","table":[["Dato","Información"],["Consulta",de(a.get("registry_query_date"))],["Dirección oficial",v(a.get("official_address"))],["Dirección usada",v(a.get("used_address"))],["Envío",de(a.get("mailing_date"))],["Resultado",v(a.get("postal_result"))],["Subsidiaria",v(a.get("secondary_notification"))],["Conocimiento real",de(a.get("actual_knowledge_date"))]]},{"heading":"II. REGLAS","numbered":notif(a)},{"heading":"III. DEFENSA MATERIAL","numbered":["Verificar oportunidad de conocer comparendo y soportes.","Verificar audiencia, pruebas y contradicción.","Verificar resolución y su notificación separada.","No presumir saneamiento por conocimiento tardío."]},{"heading":"IV. SOLICITUDES","numbered":["Decidir validez de notificación con dato histórico y trazabilidad.","Si se acredita defecto, surtir notificación procedente y efectos del art. 136.","Restablecer defensa cuando jurídicamente corresponda.","No tratar esta reclamación como suspensión automática del cobro o términos judiciales."]},sig(a,"PERSONA RECLAMANTE")]
def hearing(a,r):return [start("COMPARECENCIA Y RESERVA",["Ejercer defensa no confiesa conducción, acepta infracción ni renuncia a cuestionar notificación/evidencia."]),{"heading":"I. CUESTIONES PREVIAS","numbered":["Incorporar comparendo y prueba de vinculación.","Individualizar código, hecho, lugar y evidencia.","Precisar conducción o deber propio del propietario.","Resolver acceso al expediente."]},{"heading":"II. PRUEBAS","numbered":["Original/metadatos.","Validación y competencia.","SAST/punto y soportes.","Dato histórico y trazabilidad de notificación.","Prueba de responsabilidad personal.","Prueba de descargo."]},{"heading":"III. RESPONSABILIDAD","numbered":owner(a)},{"heading":"IV. DECISIÓN","numbered":["Contradicción efectiva.","Motivar negativa probatoria.","Explicar hechos, pruebas y norma.","Diferenciar comparendo, sanción y ejecutoria.","Notificar e informar recursos/términos."]},sig(a,"PERSONA COMPARECIENTE")]
def revocation(a,r):
 ok=bool(a.get("sanction_resolution")) and pd(a.get("sanction_date"));st="Activación documental posible" if ok else "NO RADICABLE TODAVÍA — falta individualizar y obtener el acto sancionatorio"
 return [start("ESTADO DE ACTIVACIÓN",[st,"Requiere acto, notificación, recursos, ejecutoria, demanda, pago y cobro; no sustituye recursos ni revive términos."]),{"heading":"I. ACTO","table":[["Resolución",v(a.get("sanction_resolution"))],["Fecha",de(a.get("sanction_date"))],["Notificación",v(a.get("sanction_notification"))],["Ejecutoria",de(a.get("enforceability_date"))],["Cobro",v(a.get("collection_exists"))],["Pago",v(a.get("paid"))]]},{"heading":"II. PROCEDENCIA","numbered":["Causal concreta del art. 93 CPACA y prueba.","Revisar art. 94, recursos y medio de control.","Verificar proceso judicial y art. 95.","Revisar regla especial/supletiva del art. 161 de tránsito."]},{"heading":"III. LÍMITES","numbered":["No produce silencio positivo.","No revive términos judiciales.","No suspende automáticamente ejecución/cobro/cautelares.","Decisión favorable debe ejecutarse según su alcance."]},{"heading":"IV. REVISIÓN PROFESIONAL","paragraphs":["Con término judicial, cobro, embargo, pago o acto firme, revisar expediente exacto antes de radicar."]},sig(a,"PERSONA SOLICITANTE")]
def registry(a,r):
 s=v(a.get("registry_source_act"),"Acto fuente por verificar");return [start("REGLA DE ACTIVACIÓN",["Corrección registral exige acto, pago, archivo, revocación, decisión judicial u otro soporte idóneo; una inconsistencia visual no basta.",f"Soporte: {s}."]),{"heading":"I. SOLICITUDES","numbered":["Ejecutar el acto fuente dentro de su alcance.","Actualizar base interna y transmitir novedad.","Informar fecha, identificador y resultado.","Verificar recepción y corregir residuales.","Explicar anotaciones que deban conservarse y diferenciarlas de deuda exigible."]},{"heading":"II. CIERRE","paragraphs":["Cerrar solo con evidencia del estado final de cada sistema y correspondencia con el acto fuente."]},sig(a,"PERSONA SOLICITANTE")]
def evidence(a,r):return [start("OBJETO",["Organiza soportes para decidir cada hito sin calcular consecuencias a partir de fechas incompletas."]),{"heading":"I. CRONOLOGÍA","table":tl(a)},{"heading":"II. NOTIFICACIÓN","numbered":["Dato histórico RUNT.","Canal usado y fuente.","Guía/imposición/intentos/resultado.","Subsidiaria completa.","Notificación separada de la resolución."]},{"heading":"III. RESPONSABILIDAD","numbered":owner(a)},{"heading":"IV. TÉRMINOS","numbered":terms(a)},{"heading":"V. RESULTADOS ADMISIBLES","paragraphs":["Acreditado, inconsistencia documentada, no acreditado, no calculable o escalamiento profesional; no anulación/prescripción/no pago/devolución automáticos."]}]
def guide(a,r):return [start("RADICACIÓN Y TRAZABILIDAD",["Conservar escrito/anexos, fecha/hora/canal/radicado y recepción; separar expediente contravencional, SAST y cobro."]),{"heading":"I. ALERTA DE ACTO ADVERSO","paragraphs":["Resolución, recurso, mandamiento, cautelar o providencia exige revisión inmediata de número, fecha, notificación, recursos y límite."]},{"heading":"II. SEMÁFORO","table":[["Estado","Acción"],["Comparendo sin notificación acreditada","Obtener expediente"],["Defensa abierta","Audiencia/pruebas"],["Resolución no firme","Recursos/términos"],["Resolución firme","Medio judicial/revocación/cobro"],["Mandamiento","Notificación/prescripción/excepciones"],["Embargo","Revisión urgente"],["Pago","Ruta eventual sin prometer resultado"]]},{"heading":"III. NO COLAPSAR","numbered":["Comparendo ≠ sanción.","Validación ≠ notificación.","Envío ≠ entrega.","Conocimiento tardío ≠ notificación válida.","Propietario ≠ conductor, pero puede tener deberes propios.","Falta de notificación ≠ nulidad universal.","Caducidad ≠ prescripción.","SIMIT/RUNT ≠ acto fuente.","Revocación ≠ suspensión o reapertura judicial."]},{"heading":"IV. LENGUAJE","paragraphs":["Describir acreditación y vacíos; no concluir automáticamente ‘fotomulta ilegal’, ‘multa anulada’, ‘no tiene que pagar’, ‘prescribió’ o ‘devolución obligatoria’."]},{"heading":"V. REVISIÓN HUMANA","paragraphs":["Obligatoria antes de uso externo e inmediata ante acto adverso, recurso próximo, cobro, embargo, pago o proceso judicial."]}]
B=dict(zip(K,(diagnostic,record,claim,hearing,revocation,registry,evidence,guide)))
def finalize_traffic_specs(specs:list[dict],a:dict,r:dict)->list[dict]:
 src={str(s.get("kind")):deepcopy(s) for s in specs if str(s.get("kind")) in K};meta=deepcopy(specs[0].get("metadata",[])) if specs else [];out=[]
 for k in K:
  s=src.get(k,{"kind":k,"filename_suffix":k,"metadata":meta});s.update(title=T[k],subtitle=ST[k],sections=B[k](a,r),document_standard="M33.0",internal_controls_externalized=True,requires_human_review=True,critical_human_review=str(r.get("risk")or"").casefold()=="red",legal_approval="pending",qa_approval="pending",released=False,legal_sources=list(SRC));out.append(s)
 return out
